from __future__ import annotations

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def binomial_coefficient(n, k):
    if k > n:
        return 0
    return factorial(n) // (factorial(k) * factorial(n - k))

def subsets_parity(n, k):
    if k == 0 or k == n:
        return 'ODD'
    if k == 1 or k == n - 1:
        return 'EVEN'
    if k > n // 2:
        k = n - k
    return 'EVEN' if binomial_coefficient(n, k) % 2 == 0 else 'ODD'

