from __future__ import annotations

def parse_piece_position(position):
    column = position[0]
    color = position.split('_')[1]
    return (column, color)

def update_board(board, column, color):
    for row in range(5, -1, -1):
        if board[row][column] == ' ':
            board[row][column] = color
            return board
    return board

def check_winner(board, column, color):
    for row in range(len(board)):
        for col in range(len(board[0]) - 3):
            if board[row][col] == board[row][col + 1] == board[row][col + 2] == board[row][col + 3] == color:
                return True
    for col in range(len(board[0])):
        for row in range(len(board) - 3):
            if board[row][col] == board[row + 1][col] == board[row + 2][col] == board[row + 3][col] == color:
                return True
    for row in range(len(board) - 3):
        for col in range(len(board[0]) - 3):
            if board[row][col] == board[row + 1][col + 1] == board[row + 2][col + 2] == board[row + 3][col + 3] == color:
                return True
    for row in range(3, len(board)):
        for col in range(len(board[0]) - 3):
            if board[row][col] == board[row - 1][col + 1] == board[row - 2][col + 2] == board[row - 3][col + 3] == color:
                return True
    return False

def who_is_winner(pieces_position_list):
    board = [[None for _ in range(7)] for _ in range(6)]
    players = {'Red': 'A', 'Yellow': 'B'}
    current_player = 'Red'
    for position in pieces_position_list:
        column, color = parse_piece_position(position)
        board = update_board(board, column, color)
        if check_winner(board, column, color):
            return color
        current_player = 'Yellow' if current_player == 'Red' else 'Red'
    return 'Draw'

