def format_result(result, decimals):
    return f'{result:.{decimals}f}'

def convert_to_base(number, base):
    if number == 0:
        return '0'
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if number < 0:
        sign = '-'
        number = -number
    else:
        sign = ''
    result = ''
    while number > 0:
        result = digits[int(number % base)] + result
        number //= base
    if base == pi:
        result = format_result(result, decimals)
    return sign + result

def converter(n, decimals=0, base=3.14159):
    if n == 0:
        return format_result('0', decimals)
    result = ''
    is_negative = n < 0
    n = abs(n)
    while n >= 1:
        result = str(int(n % base)) + result
        n /= base
    if n > 0:
        result += '.'
        for _ in range(decimals):
            n *= base
            digit = int(n)
            result += str(digit)
            n -= digit
    if is_negative:
        result = '-' + result
    return format_result(result, decimals)

