    parsed_terms = []
    for term in terms:
        if term.startswith('x'):
            if term == 'x':
                parsed_terms.append((1, 1))
            elif term == '-x':
                parsed_terms.append((-1, 1))
            else:
                coefficient = int(term[:-1])
                parsed_terms.append((coefficient, 1))
        elif '^' in term:
            coefficient, exponent = term.split('x^')
            parsed_terms.append((int(coefficient), int(exponent)))
        elif term.endswith('x'):
            coefficient = int(term[:-1])
            parsed_terms.append((coefficient, 1))
    return parsed_terms

