def is_valid_decomposition(sequence):
    return sequence == sorted(sequence) and all((sequence[i] < sequence[i + 1] for i in range(len(sequence) - 1)))

def generate_decomposition(n, current_sum=0, current_sequence=[]):
    if current_sum == n:
        return current_sequence
    if current_sum > n:
