from __future__ import annotations

def find_largest_square(n):
    return n * n

def is_valid_decomposition(sequence):
    return sequence == sorted(sequence) and all((sequence[i] < sequence[i + 1] for i in range(len(sequence) - 1)))

def generate_decomposition(n, current_sum=0, current_sequence=[]):
    if current_sum == n:
        return current_sequence
    if current_sum > n:
        return None
    largest_square = find_largest_square(n - current_sum)
    if largest_square == 0:
        return None
    new_sequence = current_sequence + [largest_square]
    if is_valid_decomposition(new_sequence):
        result = generate_decomposition(n, current_sum + largest_square, new_sequence)
        if result is not None:
            return result
    return generate_decomposition(n, current_sum, current_sequence)

def decompose(n):
    return generate_decomposition(n)

