from fractions import Fraction

def pascal_triangle(n):
    if n == 0:
        return [1]
    row = [1]
    for i in range(1, n + 1):
        row.append(row[i - 1] * (n - i + 1) // i)
    return row

def bernoulli_number(n):
    if n == 0:
        return Fraction(1)
    elif n == 1:
        return Fraction(-1, 2)
    pascal_row = pascal_triangle(n)
    bernoulli = Fraction(0)
    for k in range(n + 1):
        bernoulli += Fraction(pascal_row[k] * bernoulli_number(k), n + 1 - k)
    return bernoulli

