    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def reverse_number(num):
    return int(str(num)[::-1])

def is_special_number(n):
    square = n ** 2
    cube = n ** 3
    return is_prime(reverse_number(square)) and is_prime(reverse_number(cube))

