def apply_move(move, board, is_white):
    """
    Apply a single pawn move to the board.

    Args:
    move (str): The move to apply.
    board (list of list of str): Current state of the chess board.
    is_white (bool): True if it's white's turn, False if it's black's turn.

    Returns:
    list of list of str: Updated state of the chess board.
    """
    if 'x' in move:
        start_col, start_row = (ord(move[0]) - ord('a'), int(move[1]) - 1)
        end_col, end_row = (ord(move[2]) - ord('a'), int(move[3]) - 1)
        if is_white:
            if board[start_row][start_col] == 'P' and board[end_row][end_col] == 'p':
                board[start_row][start_col] = '.'
                board[end_row][end_col] = 'P'
            else:
                return f'{move} is invalid'
        elif board[start_row][start_col] == 'p' and board[end_row][end_col] == 'P':
            board[start_row][start_col] = '.'
