def extract_outer_layer(array):
    if not array or not array[0]:
        return []
    top = array[0]
    bottom = array[-1]
    left = [row[0] for row in array[1:-1]]
    right = [row[-1] for row in array[1:-1]]
    return top + right + bottom[::-1] + left[::-1]

def remove_outer_layer(array):
    return array[1:-1, 1:-1]

def snail(array):
    if not array:
        return []
    result = []
    while array:
        result += extract_outer_layer(array)
        array = remove_outer_layer(array)
    return result

