def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def permutation_count(n, k):
    if k == 0:
        return 1
    return n * permutation_count(n - 1, k - 1)

def find_middle_index(n):
    if n % 2 == 0:
        return n // 2
    else:
        return n // 2

def middle_permutation(string):
    n = len(string)
    middle_index = find_middle_index(n)
    factorial_n = factorial(n)
    permutation_count_n_minus_1 = permutation_count(n - 1, n - 1)
    result = []
    for i in range(n):
        char = string[i]
        count = 0
        for j in range(n):
            if j != i and string[j] < char:
                count += 1
        result.append(char)
        n -= 1
